UPDATE MBW_BOOTSTRAP_APPROVAL
   SET STATUS = 'CLAIMED', OPERATION_ID = :operationId, CLAIM_OWNER_ID = :claimOwnerId,
       CLAIMED_AT = SYS_EXTRACT_UTC(SYSTIMESTAMP), CLAIM_EXPIRES_AT = SYS_EXTRACT_UTC(SYSTIMESTAMP) + NUMTODSINTERVAL(:leaseDurationMicros / 1000000, 'SECOND'),
       UPDATED_AT = SYS_EXTRACT_UTC(SYSTIMESTAMP)
 WHERE TOKEN_HASH = :tokenHash
   AND ENV_FINGERPRINT = :environmentFingerprint
   AND EXPIRES_AT > SYS_EXTRACT_UTC(SYSTIMESTAMP)
   AND (
        STATUS = 'APPROVED'
        OR (STATUS = 'CLAIMED' AND OPERATION_ID = :operationId AND CLAIM_EXPIRES_AT <= SYS_EXTRACT_UTC(SYSTIMESTAMP))
   )
